import test from 'node:test';
import assert from 'node:assert/strict';
import { quoteStake, payoutScenario, UINT72_MAX } from '../../src/domain/calculator.ts';
import { parseUnits, displayRatio } from '../../src/domain/units.ts';
import { HEX_LAUNCH_SECONDS, newStakeTiming } from '../../src/domain/day.ts';

// Independently computed with Python Fraction from the two percentage definitions;
// literal witnesses, not outputs generated by the TypeScript helper (see reference.md).
const vectors = [
  ['1', 1, '100000', '0', '1'],
  ['1', 3640, '100000', '1', '2'],
  ['1', 3641, '100000', '2', '3'],
  ['1', 5555, '100000', '2', '3'],
  ['100000000001', 2, '123456', '55011721', '81045078183'],
  ['14999999999999999', 3640, '123456', '31491758241758239', '37658565190641392'],
  ['15000000000000000', 3641, '123456', '31500000000000000', '37665241057542768'],
  ['15000000000000001', 5555, '123456', '31500000000000002', '37665241057542770'],
  ['1000000000000', 365, '123456', '200006666666', '972011620873'],
  ['4722366482869645213695', 1, '1099511627775', '472236648286964521369', '472446402560429'],
];
test('new stake issuance: independent combined-floor, caps, neighbors and raw-rate witnesses', () => {
  for (const [hearts, days, rate, bonus, shares] of vectors) {
    const q = quoteStake(BigInt(hearts), days, BigInt(rate), HEX_LAUNCH_SECONDS + 5000n * 86400n);
    assert.equal(String(q.bonusHearts), bonus);
    assert.equal(String(q.stakeShares), shares);
  }
  // Separate bonus floors would give 55011720 and therefore different shares.
  assert.equal(
    quoteStake(100000000001n, 2, 1n, HEX_LAUNCH_SECONDS).stakeShares,
    10005501172200000n,
  );
});
test('calculator rejects unsupported inputs, zero issuance and uint overflows', () => {
  for (const days of [0, 5556, 1.5, NaN])
    assert.throws(() => quoteStake(100n, days, 100000n, HEX_LAUNCH_SECONDS));
  for (const amount of [0n, -1n, UINT72_MAX + 1n])
    assert.throws(() => quoteStake(amount, 1, 100000n, HEX_LAUNCH_SECONDS));
  for (const rate of [0n, -1n, 1n << 40n])
    assert.throws(() => quoteStake(100n, 1, rate, HEX_LAUNCH_SECONDS));
  assert.throws(() => quoteStake(1n, 1, 100001n, HEX_LAUNCH_SECONDS), /positive uint72/);
  assert.throws(() => quoteStake(UINT72_MAX, 5555, 1n, HEX_LAUNCH_SECONDS), /positive uint72/);
  for (const amount of ['1e5', '-1', '1,000', '.1', '1.000000001'])
    assert.throws(() => parseUnits(amount, 8));
});
test('calculator timing retains UTC lock boundary, launch floor and far-future refusal', () => {
  assert.equal(quoteStake(100n, 1, 100000n, HEX_LAUNCH_SECONDS).lockedDay, 2);
  const before = quoteStake(100n, 365, 100000n, HEX_LAUNCH_SECONDS + 501n * 86400n - 1n);
  const after = quoteStake(100n, 365, 100000n, HEX_LAUNCH_SECONDS + 501n * 86400n);
  assert.equal(before.maturityDay, 866);
  assert.equal(after.maturityDay, 867);
  assert.deepEqual(newStakeTiming(HEX_LAUNCH_SECONDS + 65533n * 86400n, 1).maturityDay, 65535);
  assert.throws(() => quoteStake(100n, 2, 100000n, HEX_LAUNCH_SECONDS + 65533n * 86400n));
});
test('scenario uses exact mean 13/42, exact share scaling and hypothetical future USD', () => {
  const q = {
    ...quoteStake(100n, 1, 100000n, HEX_LAUNCH_SECONDS),
    principalHearts: 100000000n,
    stakeShares: 2000000000000n,
    days: 21,
  };
  const scenario = payoutScenario(
    q,
    { numerator: 13n, denominator: 42n },
    { numerator: 1n, denominator: 8n },
  );
  assert.equal(displayRatio(scenario.rewardHex), '13');
  assert.equal(displayRatio(scenario.totalHex), '14');
  assert.equal(displayRatio(scenario.usd), '1.75');
  assert.equal(payoutScenario(q, { numerator: 13n, denominator: 42n }, null).usd, null);
  assert.throws(() => payoutScenario(q, { numerator: 13n, denominator: 0n }, null));
});
